import { pathToFileURL } from "node:url";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { mkdirSync,readFileSync,writeFileSync } from "node:fs";
import { join } from "node:path";
import Database from "better-sqlite3";
import { canonicalDigest } from "../../src/domain/request-digest";
import { boundedLaunch,boundedPair,boundedProxy } from "./w01-runtime";
import { invokeCli } from "./w01-legacy-performance";
import { captureEventSpool,validateEventSpool } from "./w01-spool";
import { copySeed,type W02Prepared } from "./w02-preparation";
import { summarizeSamples,teardownAll,validateGeneration,validateCliClock,validateReceiptBody } from "./w02-measurement";
export const oldHTTP=["boardSnapshot","taskSnapshot","implementationRegistration","implementationSuccess","completion","reopen","taskCreationDefaultFullHTTP"];
export const oldCLI=["implementationRegistrationCLI","implementationReportCLI","taskCreatePreference"];
export const newHTTP=["dependencies","policy","artifact","rework","readiness","gateRead","artifactHistory","decisionHistory","reworkHistory","gateReport","workflowReadiness"];
import { mutationGate,capturedHttp,httpFact,type HttpFact } from "./w02-mutation";
export type Transport=HttpFact & {setup?:boolean;cliArgs?:string[];cli?:Awaited<ReturnType<typeof invokeCli>>;spool?:unknown;row?:unknown;projectedStoredReceipt?:unknown};
export async function operationRun(p:W02Prepared,label:"base"|"head",repetition:number,root:string,samples:number,warmups:number,save:()=>void,raw:Transport[],failures:unknown[],newOnly=false){
 const firstRaw=raw.length,dir=copySeed(p,newOnly?"scenario":label,join(root,`${label}-${newOnly?"new-":""}${repetition}`)),server=await boundedLaunch({dir,cwd:p.sources[label]}),resources=[{name:"service",close:server.stop}];let primary:unknown;const result:Record<string,ReturnType<typeof summarizeSamples>>={};try{
  const contracts=await import(pathToFileURL(join(p.sources[label],"src/contracts/routes.ts")).href);const cookie=await boundedPair(server),seed=p.seeds[label],token=join(dir,"cli-token");writeFileSync(token,server.credentials().reporterToken,{mode:0o600});const outbox=join(root,`${label}-${newOnly?"new-":""}${repetition}-outbox`);mkdirSync(outbox,{mode:0o700});let sequence=0,setupSequence=0;const gate=mutationGate();let activeParent:Transport|undefined;let activeCli:Transport|undefined;
  async function http(path:string,input:unknown=undefined,method="GET",operator=false,record?:Transport){
   const target=record??httpFact({dataDir:dir,id:activeParent!.id+":http-setup-"+setupSequence++,parentSampleId:activeParent!.id,setup:true,warmup:activeParent!.warmup,label,operation:activeParent!.operation});if(!record)raw.push(target);const headers:Record<string,string>=operator?{Cookie:cookie,Origin:server.url}:{Authorization:"Bearer "+server.credentials().reporterToken};
   try{const parsed=await capturedHttp(server.url+"/api/v1"+path,input,method,headers,target,save,gate),contract=contracts.matchEndpoint(method,new URL(server.url+"/api/v1"+path).pathname);assert(contract,"source-correct endpoint contract required");contract.endpoint.response.parse(parsed);validateGeneration(target.generation,parsed);return parsed.data;}catch(error){target.failure=String(error);try{save();}catch(persist){target.persistenceFailure=String(persist);}throw error;}
  }
  const proxy=await boundedProxy(server,(request,body,reply)=>{if(request.method!=="POST")return undefined;if(!reply){const target=activeCli;if(!target)return undefined;if(target?.cli===undefined&&target?.operation.includes("CLI")||target?.operation==="taskCreatePreference"){if(request.url?.endsWith("/events")){const event=JSON.parse(body.toString());const capture=captureEventSpool(outbox,{kind:"run",id:event.runId},event);validateEventSpool(capture,event);target!.spool=capture;}else if(request.headers["idempotency-key"]){const path=join(outbox,`registration-${request.headers["idempotency-key"]}.json`),bytes=readFileSync(path);target!.spool={originalBytesBase64:bytes.toString("base64"),record:JSON.parse(bytes.toString())};}if(target){target.path=request.url??"";target.method=request.method??"";target.body=body.toString();target.input=JSON.parse(body.toString());target.key=String(request.headers["idempotency-key"]??"");save();}}}else{const target=activeCli;if(!target)return undefined;if(target){target.status=reply.status;target.text=reply.body.toString();target.generation=reply.generation;target.retryAfter=reply.retryAfter;save();if(reply.status<200||reply.status>=300){target.failure=`HTTP ${reply.status} ${target.method} ${target.path}`;save();throw Error(target.failure);}validateGeneration(target.generation,JSON.parse(target.text));}}return undefined;});resources.unshift({name:"proxy",close:proxy.close});
  const env={PORT:String(proxy.port),AGENTFLOW_REPORTER_TOKEN_FILE:token,AGENTFLOW_OUTBOX_DIR:outbox};const cliFile=(input:unknown)=>{const path=join(dir,`cli-${sequence++}.json`);writeFileSync(path,JSON.stringify(input),{mode:0o600});return path;};
  async function task(){return http("/tasks",{projectId:seed.projectId,title:"Synthetic W02 measurement "+sequence++},"POST");}
  async function implementation(t:{id:string;version:number},terminal=false){const id=randomUUID();await http("/runs",{id,projectId:seed.projectId,taskId:t.id,agentId:seed.agents[0],purpose:"implementation",expectedTaskVersion:t.version},"POST");await event(id,1,"run.started",{});if(terminal)await event(id,2,"run.succeeded",{summary:"Synthetic",artifactRef:"synthetic:tuple"});return id;}
  function event(id:string,n:number,type:string,payload:unknown,record?:Transport){return http(`/runs/${id}/events`,{schemaVersion:1,eventId:randomUUID(),runId:id,sequence:n,type,occurredAt:new Date().toISOString(),payload},"POST",false,record);}
  const operations=newOnly?newHTTP:[...oldHTTP,...oldCLI];
  for(const operation of operations){const expected=p.samples.filter(e=>e.label===label&&e.repetition===repetition&&e.operation===operation);assert.equal(expected.length,samples+warmups);assert.equal(expected.filter(e=>e.warmup).length,warmups);const captured:Transport[]=[];
   for(const identity of expected){const r:Transport=httpFact({dataDir:dir,...identity,parentSampleId:identity.id,setup:false,operation,label});activeParent=r;let t:{id:string;version:number}|undefined,runId:string|undefined;if(!["boardSnapshot","taskSnapshot","readiness","gateRead","artifactHistory","decisionHistory","reworkHistory","workflowReadiness"].includes(operation))t=await task();
    if(operation==="implementationSuccess")runId=await implementation(t!);
    if(["completion","reopen","rework"].includes(operation)){await http(`/tasks/${t!.id}`,{expectedVersion:t!.version,status:"review"},"PATCH",true);t=(await http(`/tasks/${t!.id}`)).task;if(operation==="reopen"){await http(`/tasks/${t!.id}/complete`,{expectedVersion:t!.version,evidenceNote:"Synthetic accepted"},"POST",true);t=(await http(`/tasks/${t!.id}`)).task;}}
    if(operation==="gateReport"){await http(`/tasks/${t!.id}/review-policy`,{expectedVersion:t!.version,reviewRequired:true,verificationRequired:false},"PATCH",true);t=(await http(`/tasks/${t!.id}`)).task;await implementation(t!,true);t=(await http(`/tasks/${t!.id}`)).task;runId=randomUUID();await http("/runs",{id:runId,projectId:seed.projectId,taskId:t!.id,agentId:seed.agents[0],purpose:"review",expectedTaskVersion:t!.version,workRevision:(t as {workRevision?:number}).workRevision,artifactRef:"synthetic:tuple",reworkRound:0},"POST");await event(runId,1,"run.started",{});}
    if(operation==="implementationReportCLI"){runId=randomUUID();for(const [part,args] of [["register",["run","register","--file",cliFile({id:runId,projectId:seed.projectId,taskId:t!.id,agentId:seed.agents[0],purpose:"implementation",expectedTaskVersion:t!.version}),"--idempotency-key",randomUUID()]],["start",["report","--run",runId,"--type","run.started","--payload",cliFile({})]]] as [string,string[]][]){const setup:Transport={...r,id:r.id+":setup-"+part,operation:"implementationReportCLISetup",setup:true,cliArgs:args};raw.push(setup);activeCli=setup;save();try{setup.cli=await gate.run(()=>invokeCli(p.sources[label],args,env),pacing=>{setup.pacing=pacing;});Object.assign(setup,{elapsedMs:setup.cli.elapsedMs,dispatchMs:setup.cli.dispatchMs,drainedMs:setup.cli.drainedMs});save();validateCliClock(setup.cli);}finally{activeCli=undefined;}}}
    raw.push(r);captured.push(r);save();
    if(operation==="boardSnapshot")await http(`/projects/${seed.projectId}/board`,undefined,"GET",false,r);
    else if(operation==="taskSnapshot")await http(`/tasks/${seed.tasks[50]}`,undefined,"GET",false,r);
    else if(operation==="taskCreationDefaultFullHTTP")await http("/tasks",{projectId:seed.projectId,title:"Synthetic full response"},"POST",false,r);
    else if(operation==="implementationRegistration")await http("/runs",{id:randomUUID(),projectId:seed.projectId,taskId:t!.id,agentId:seed.agents[0],purpose:"implementation",expectedTaskVersion:t!.version},"POST",false,r);
    else if(operation==="implementationSuccess")await event(runId!,2,"run.succeeded",{summary:"Synthetic disabled-policy success"},r);
    else if(operation==="completion")await http(`/tasks/${t!.id}/complete`,{expectedVersion:t!.version,evidenceNote:"Synthetic human acceptance"},"POST",true,r);
    else if(operation==="reopen")await http(`/tasks/${t!.id}/reopen`,{expectedVersion:t!.version,reason:"Synthetic new work"},"POST",true,r);
    else if(operation==="dependencies")await http(`/tasks/${t!.id}/dependencies`,{expectedVersion:t!.version,prerequisiteIds:[seed.tasks[50]]},"PUT",true,r);
    else if(operation==="policy")await http(`/tasks/${t!.id}/review-policy`,{expectedVersion:t!.version,reviewRequired:true,verificationRequired:true},"PATCH",true,r);
    else if(operation==="artifact")await http(`/tasks/${t!.id}/artifact`,{expectedVersion:t!.version,artifactRef:"synthetic:operator"},"POST",true,r);
    else if(operation==="rework")await http(`/tasks/${t!.id}/rework`,{expectedVersion:t!.version,reason:"Synthetic fresh tuple"},"POST",true,r);
    else if(operation==="readiness")await http(`/tasks/${seed.tasks[50]}/readiness`,undefined,"GET",false,r);
    else if(operation==="gateRead")await http(`/tasks/${p.diamond[3]}`,undefined,"GET",false,r);
    else if(["artifactHistory","decisionHistory","reworkHistory"].includes(operation))await http(`/tasks/${p.diamond[3]}/${operation==="artifactHistory"?"artifacts":operation==="decisionHistory"?"decisions":"reworks"}?limit=20`,undefined,"GET",false,r);
    else if(operation==="workflowReadiness")await http(`/workflows/${p.workflow.workflowId}/revisions/${p.workflow.revisionId}/readiness`,undefined,"GET",false,r);
    else if(operation==="gateReport")await event(runId!,2,"run.succeeded",{summary:"Synthetic review",decision:"approved",evidenceNote:"Synthetic gate report"},r);
    else {const args=operation==="taskCreatePreference"?["task","create","--file",cliFile({projectId:seed.projectId,title:"Synthetic minimal CLI"}),"--idempotency-key",randomUUID()]:operation==="implementationRegistrationCLI"?["run","register","--file",cliFile({id:randomUUID(),projectId:seed.projectId,taskId:t!.id,agentId:seed.agents[0],purpose:"implementation",expectedTaskVersion:t!.version}),"--idempotency-key",randomUUID()]:["report","--run",runId!,"--type","run.succeeded","--payload",cliFile({summary:"Synthetic CLI success"})];r.cliArgs=args;activeCli=r;save();try{r.cli=await gate.run(()=>invokeCli(p.sources[label],args,env),pacing=>{r.pacing=pacing;});Object.assign(r,{elapsedMs:r.cli.elapsedMs,dispatchMs:r.cli.dispatchMs,drainedMs:r.cli.drainedMs});save();validateCliClock(r.cli);}finally{activeCli=undefined;}}
    save();assert(r.status!==null&&r.status>=200&&r.status<300);}
   result[operation]=summarizeSamples(expected,captured);save();}
 }catch(error){primary=error;}finally{await teardownAll(primary,resources,failures);}
 const taskProjection=await import(pathToFileURL(join(p.sources[label],"src/contracts/task-registration.ts")).href);const db=new Database(join(dir,"agentflow.sqlite"),{readonly:true});try{for(const r of raw.slice(firstRaw)){if(r.method==="GET")continue;if(r.path.endsWith("/events")){const input=r.input as {eventId:string};r.row=db.prepare("SELECT * FROM run_events WHERE event_id=?").get(input.eventId);assert(r.row);const row=r.row as {digest:string;acknowledgement:string};assert.equal(row.digest,canonicalDigest(r.input));assert.deepEqual(JSON.parse(row.acknowledgement),JSON.parse(r.text!));}else{r.row=db.prepare("SELECT * FROM receipts WHERE key=? AND path=?").get(r.key,r.path);assert(r.row);const row=r.row as {digest:string;body:string};assert.equal(row.digest,canonicalDigest(r.input));r.projectedStoredReceipt=validateReceiptBody(JSON.parse(row.body),JSON.parse(r.text!),r.operation==="taskCreatePreference",taskProjection.projectTaskRegistration);}save();}assert.deepEqual(db.pragma("foreign_key_check"),[]);}finally{db.close();}return result;
}
